/** Evaluation only: model execution belongs to an explicitly supplied host.
 * Semantic judgments are independent inputs, never generated by the tidy model. */
import { z } from 'zod';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { GraphMemory } from '../core/graph-memory.js';
import { driveOrganizationRequest } from '../core/organization-driver.js';
import { ORGANIZATION_POLICY } from '../core/organization-policy.js';
import { digest, stableJSON } from '../core/growth.js';
import { retrievalStatus } from '../core/retrieval-status.js';
import type { ModelCallContext } from '../core/work-driver.js';
const str=z.string().trim().min(1);
const caseSchema=z.object({id:str,group:str,split:z.enum(['development','holdout']),tags:z.array(str).min(1),
  memories:z.array(z.object({id:str,content:str})).min(2).max(24),
  associations:z.array(z.object({a:str,b:str,reason:str,context:str,weight:z.number().min(0).max(1)})).default([]),
  facts:z.array(z.object({id:str,claim:str})).min(1),forbidden:z.array(str),
  expectRestraint:z.boolean(),expectAssociation:z.boolean()});
export const qualityDatasetSchema=z.object({version:z.literal('mindpond.organization-quality.v1'),description:str,cases:z.array(caseSchema).min(1)});
export type QualityDataset=z.infer<typeof qualityDatasetSchema>;
export interface QualityAdapter {
  id:string;modelId:string;kind:'live'|'synthetic';supportsCancel?:boolean;
  parameters:Record<string,unknown>;
  generate(prompt:string,context:ModelCallContext):Promise<{text:string;modelId:string;usage?:{inputTokens?:number;outputTokens?:number;cost?:number;currency?:string}}>;
}
export function validateQualityDataset(raw:unknown):QualityDataset {
  const data=qualityDatasetSchema.parse(raw),ids=new Set<string>(),groups=new Map<string,string>();
  for(const c of data.cases){
    if(ids.has(c.id))throw new Error('Duplicate case id: '+c.id);ids.add(c.id);
    if(groups.has(c.group)&&groups.get(c.group)!==c.split)throw new Error('Source group leaks across development and holdout: '+c.group);
    groups.set(c.group,c.split);
    if(new Set(c.memories.map(m=>m.id)).size!==c.memories.length||new Set(c.facts.map(f=>f.id)).size!==c.facts.length)throw new Error('Duplicate memory/fact id: '+c.id);
    for(const a of c.associations)if(a.a===a.b||!c.memories.some(m=>m.id===a.a)||!c.memories.some(m=>m.id===a.b))throw new Error('Invalid association endpoints: '+c.id);
  }
  return data;
}
export async function runOrganizationQuality(data:QualityDataset,adapter:QualityAdapter,options:{budgetMs:number;maxAttempts:number}) {
  data=validateQualityDataset(data);
  if(!adapter.id||!adapter.modelId||!['live','synthetic'].includes(adapter.kind)||typeof adapter.generate!=='function')throw new Error('Adapter must declare id, modelId, live/synthetic kind and generate');
  const temp=await fs.mkdtemp(path.join(os.tmpdir(),'mindpond-quality-')),cases:any[]=[];
  try {
    for(const spec of data.cases){
      const graph=new GraphMemory('.',{dbPath:path.join(temp,randomUUID()+'.db')}),calls:any[]=[];
      const started=Date.now();
      try {
        await graph.init();
        const ids=new Map<string,string>(),scope={spaceId:'eval/'+spec.id,memoryType:'fact'};
        // Only input memories and original relationship context enter the graph.
        // Rubric/facts/forbidden conclusions are NEVER appended to model material.
        for(const m of spec.memories){const saved=await graph.saveMemory(m.content,{memberships:[scope],sourceRefs:[{uri:'fixture:'+spec.id+'/'+m.id,context:'fixed-evaluation',revision:data.version}]});ids.set(m.id,saved.id);}
        for(const a of spec.associations)await graph.upsertAssociation((await graph.getMemberships(ids.get(a.a)!))[0].id,(await graph.getMemberships(ids.get(a.b)!))[0].id,scope.spaceId,scope.memoryType,a.weight,{reason:a.reason,context:a.context});
        const initialAssociationIds=(await graph.listAssociations()).map(a=>a.id);
        const request=await graph.organizationRequests.createRequest({...scope,batchSize:Math.min(8,spec.memories.length),limit:spec.memories.length,idempotencyKey:'fixed-eval'});
        const progress=await driveOrganizationRequest(graph,{requestId:request.requestId,...options,llm:{supportsCancel:adapter.supportsCancel,generate:async(prompt,ctx)=>{
          const call:any={prompt,promptDigest:digest(prompt),startedAt:Date.now()};calls.push(call);
          try {
            const response=await adapter.generate(prompt,ctx);
            call.response=response;call.finishedAt=Date.now();
            if(typeof response?.text!=='string'||response.modelId!==adapter.modelId)throw new Error('Host must report the exact pinned response modelId');
            return response.text;
          } catch(error){call.error=String(error);call.finishedAt=Date.now();throw error;}
        }}});
        const final=await graph.listNodes({spaceId:scope.spaceId,memoryType:scope.memoryType,activeOnly:true,limit:500});
        const relations=await graph.listAssociations();
        cases.push({caseId:spec.id,split:spec.split,group:spec.group,spec,inputIds:Object.fromEntries(ids),progress,calls,
          activeMemories:final.nodes,associations:relations,initialAssociationIds,elapsedMs:Date.now()-started,
          engineeringPassed:progress.status==='completed'&&progress.concluded.failed===0&&progress.concluded.uncovered===0});
      } catch(error){cases.push({caseId:spec.id,split:spec.split,group:spec.group,spec,calls,error:String(error),elapsedMs:Date.now()-started,engineeringPassed:false});}
      finally {await graph.close();}
    }
    const allCalls=cases.flatMap(c=>c.calls??[]),measured=allCalls.filter(c=>c.response?.usage);
    const cost={modelCalls:allCalls.length,callsWithUsage:measured.length,callsWithoutUsage:allCalls.length-measured.length,
      inputTokens:measured.reduce((n,c)=>n+(c.response.usage.inputTokens??0),0),outputTokens:measured.reduce((n,c)=>n+(c.response.usage.outputTokens??0),0),
      reportedCosts:measured.filter(c=>typeof c.response.usage.cost==='number').map(c=>({amount:c.response.usage.cost,currency:c.response.usage.currency??'unspecified'})),
      elapsedMs:cases.reduce((n,c)=>n+c.elapsedMs,0)};
    return {version:'mindpond.quality-run.v1',runId:randomUUID(),generatedAt:new Date().toISOString(),datasetDigest:digest(stableJSON(data)),
      adapter:{id:adapter.id,modelId:adapter.modelId,kind:adapter.kind,parameters:adapter.parameters},config:options,
      organizationPolicyDigest:digest(ORGANIZATION_POLICY),retrieval:retrievalStatus(),cost,cases,
      qualityStatus:'unreviewed',releasePassed:false,scope:'Organization only. Does not prove retrieval or downstream task improvement.'};
  } finally {await fs.rm(temp,{recursive:true,force:true});}
}

const judgmentSchema=z.object({runDigest:str,reviewerId:str,independent:z.literal(true),cases:z.array(z.object({caseId:str,
  severeErrors:z.array(str),facts:z.array(z.object({id:str,preserved:z.boolean(),direct:z.boolean(),evidence:str})),
  forbidden:z.array(z.object({claim:str,absent:z.boolean(),evidence:str})),
  restraintCorrect:z.boolean().nullable(),validOutcome:z.boolean(),associations:z.array(z.object({id:str,valid:z.boolean(),evidence:str})),
  requiredAssociationIds:z.array(str),notes:str}))});
export function gradeOrganizationQuality(run:Awaited<ReturnType<typeof runOrganizationQuality>>,raw:unknown) {
  const judgments=judgmentSchema.parse(raw);
  const withDigest=run as typeof run & {reviewDigest?:string};
  const {reviewDigest,...unsigned}=withDigest;
  const actualDigest=digest(stableJSON(unsigned));
  if(reviewDigest!==undefined&&reviewDigest!==actualDigest)throw new Error('Run artifact changed after sealing');
  if(judgments.runDigest!==actualDigest)throw new Error('Judgments are for another exact run artifact');
  const byId=new Map(judgments.cases.map(j=>[j.caseId,j]));
  if(byId.size!==judgments.cases.length||byId.size!==run.cases.length)throw new Error('Every case needs exactly one independent judgment');
  const totals={cases:0,groups:0,facts:0,preserved:0,direct:0,severe:0,restraint:0,restraintCorrect:0,relations:0,validRelations:0,requiredRelations:0,foundRequiredRelations:0,engineering:0,validOutcomes:0};
  const holdoutGroups=new Set<string>(),holdoutTags=new Map<string,number>();
  for(const c of run.cases){
    const j=byId.get(c.caseId);if(!j)throw new Error('Missing judgment: '+c.caseId);
    const same=(a:string[],b:string[])=>stableJSON([...a].sort())===stableJSON([...b].sort());
    if(!same(j.facts.map(f=>f.id),c.spec.facts.map((f:any)=>f.id))||!same(j.forbidden.map(f=>f.claim),c.spec.forbidden))throw new Error('Incomplete fact/forbidden rubric: '+c.caseId);
    if(!same(j.associations.map(a=>a.id),(c.associations??[]).map((a:any)=>a.id)))throw new Error('Every final association needs a judgment: '+c.caseId);
    if(j.facts.some(f=>f.direct&&!f.preserved))throw new Error('Direct coverage cannot exceed preserved information: '+c.caseId);
    if(c.spec.expectRestraint&&j.restraintCorrect===null)throw new Error('Missing restraint judgment: '+c.caseId);
    if(new Set(j.requiredAssociationIds).size!==j.requiredAssociationIds.length)throw new Error('Duplicate required relationship id: '+c.caseId);
    if(!c.spec.expectAssociation&&j.requiredAssociationIds.length)throw new Error('Unexpected required relationship ids: '+c.caseId);
    const initialAssociationIds=new Set<string>(c.initialAssociationIds??[]);
    for(const id of j.requiredAssociationIds)if(initialAssociationIds.has(id)||!j.associations.some(a=>a.id===id&&a.valid))
      throw new Error('Required relationship must be a newly added, independently valid final association: '+c.caseId);
    if(c.split!=='holdout')continue;
    totals.cases++;holdoutGroups.add(c.group);for(const tag of c.spec.tags)holdoutTags.set(tag,(holdoutTags.get(tag)??0)+1);
    totals.facts+=j.facts.length;totals.preserved+=j.facts.filter(f=>f.preserved).length;totals.direct+=j.facts.filter(f=>f.direct).length;
    totals.severe+=j.severeErrors.length+j.forbidden.filter(f=>!f.absent).length;
    if(c.spec.expectRestraint){totals.restraint++;if(j.restraintCorrect)totals.restraintCorrect++;}
    totals.relations+=j.associations.length;totals.validRelations+=j.associations.filter(a=>a.valid).length;
    if(c.spec.expectAssociation){
      totals.requiredRelations++;
      if(j.requiredAssociationIds.length)totals.foundRequiredRelations++;
    }
    if(c.engineeringPassed)totals.engineering++;if(c.engineeringPassed&&j.validOutcome)totals.validOutcomes++;
  }
  const rate=(n:number,d:number)=>d?n/d:null;
  totals.groups=holdoutGroups.size;
  const metrics={keyInformation:rate(totals.preserved,totals.facts),directInformation:rate(totals.direct,totals.facts),restraint:rate(totals.restraintCorrect,totals.restraint),associationPrecision:rate(totals.validRelations,totals.relations),associationRecall:rate(totals.foundRequiredRelations,totals.requiredRelations),engineering:rate(totals.engineering,totals.cases),taskCorrectness:rate(totals.validOutcomes,totals.cases)};
  const blockers:string[]=[];
  if(run.adapter.kind!=='live')blockers.push('synthetic_model');
  if(run.cases.length<120||new Set(run.cases.map(c=>c.group)).size<120||totals.cases<40||totals.groups<40)blockers.push('insufficient_independent_cases');
  for(const tag of ['duplicate','complement','unrelated','conflict','association-context','code-profile','anchor','domain'])
    if((holdoutTags.get(tag)??0)<5)blockers.push('insufficient_holdout_tag:'+tag);
  if(totals.severe)blockers.push('severe_semantic_error');
  if(metrics.keyInformation===null||metrics.keyInformation<.98)blockers.push('information_retention');
  if(metrics.restraint===null||metrics.restraint<.95)blockers.push('restraint');
  if(metrics.associationPrecision===null||metrics.associationPrecision<.95)blockers.push('association_precision');
  if(totals.requiredRelations<5)blockers.push('insufficient_required_relations');
  if(metrics.associationRecall===null||metrics.associationRecall<.95)blockers.push('association_coverage');
  if(metrics.engineering===null||metrics.engineering<.95)blockers.push('engineering_completion');
  if(metrics.taskCorrectness===null||metrics.taskCorrectness<.95)blockers.push('task_correctness');
  return {runId:run.runId,runDigest:judgments.runDigest,reviewerId:judgments.reviewerId,totals,metrics,blockers,releasePassed:blockers.length===0,
    limitations:'Thresholds cover this fixed organization benchmark only; retrieval and real task trials remain separate.'};
}
